"""Original solid-tumor questions: breast and gastrointestinal cancers."""
from create_oncology_lung_breast import rows,q,LU,SL,BR,MO,ref
CR=ref('NCI colon cancer professional summary','https://www.cancer.gov/types/colorectal/hp/colon-treatment-pdq')
GA=ref('NCI gastric cancer professional summary','https://www.cancer.gov/types/stomach/hp/stomach-treatment-pdq')
PA=ref('NCI pancreatic cancer professional summary','https://www.cancer.gov/types/pancreatic/hp/pancreatic-treatment-pdq')

q('A breast tumor lacks ER, PR and HER2 overexpression/amplification. Which statement is correct?', 'It is classified as triple-negative by these standard receptor tests, but further biomarkers and disease setting can still guide treatment',[
 ('Standard endocrine therapy is indicated solely from the triple-negative label','The required hormone-receptor target is absent.'),('The tumor has no possible systemic treatment','Chemotherapy and selected immune/targeted strategies can be relevant.'),('All triple-negative cancers are biologically identical','The group is heterogeneous.')],
 'A receptor-defined category does not exhaust tumor biology','**Triple-negative describes absence of the three standard receptor signals.**',['Germline BRCA status and other biomarkers can matter.','Stage and prior treatment affect options.'],'**Use current subtype- and setting-specific evidence.**',['Do not extrapolate an indication from another breast subtype.','Assess hereditary risk when appropriate.'],[['Definition','ER−/PR−/HER2 non-overexpressed'],['Biology','Heterogeneous'],['Treatment','Setting and additional biomarkers']],[BR])

q('A breast-cancer HER2 IHC result is 2+. What is the appropriate next interpretive step for conventional HER2 amplification/overexpression classification?', 'Reflex appropriate in situ hybridization and integrated interpretation',[
 ('Call every IHC 2+ tumor amplified without further testing','The category is equivocal for this classification.'),('Call every IHC 2+ tumor IHC 0','These are different results.'),('Use serum HER2 as a universal replacement for tissue interpretation','The validated algorithm is tissue-based.')],
 'Equivocal protein expression needs the specified algorithm','**IHC and ISH can provide complementary HER2 information.**',['ISH patterns require integrated interpretation with IHC in selected groups.','Lower-expression treatment categories are a separate indication question.'],'**Report the exact assay result and apply current therapy criteria.**',['Do not confuse nonamplified with absence of every HER2 protein molecule.','Preserve accurate low-expression scoring when relevant to an ADC indication.'],[['IHC 2+','Reflex ISH'],['Amplification classification','Integrated result'],['Therapy','Current indication-specific criteria']],[ref('ASCO–CAP HER2 breast testing algorithm','https://documents.cap.org/documents/her2_breast_update_algorithms_2023.pdf')])

q('A man is diagnosed with breast cancer. Which additional assessment is important?', 'Evaluate hereditary cancer risk and offer indicated germline testing/counseling',[
 ('Male sex excludes a BRCA-related syndrome','Male breast cancer can be associated with inherited susceptibility.'),('The diagnosis proves a germline mutation without testing','An association is not confirmation.'),('Family history is irrelevant because only women inherit these variants','Autosomal inherited variants can pass through either sex.')],
 'An uncommon presentation can be a hereditary-risk clue','**BRCA2 and other susceptibility genes can be relevant in male breast cancer.**',['The result may affect treatment and relatives’ care.','Consent and interpretation are important.'],'**Use a genetics-informed care pathway.**',['Do not act on an uncertain variant as though pathogenic.','Assess the patient’s own broader cancer risk when a pathogenic variant is confirmed.'],[['Presentation','Male breast cancer'],['Concern','Hereditary susceptibility'],['Action','Appropriate counseling/testing']],[BR,ref('NCI BRCA risk and genetic testing','https://www.cancer.gov/about-cancer/causes-prevention/genetics/brca-fact-sheet')],style='clinical_scenario')

q('A persistent breast lump is present despite a reassuring serum tumor-marker panel. Which diagnostic approach is appropriate?', 'Clinical assessment with appropriate breast imaging and tissue sampling when indicated',[
 ('Use normal markers to exclude cancer','Markers are not a reliable rule-out test for a breast mass.'),('Treat every lump as malignant without imaging or tissue context','Benign causes exist and diagnosis needs assessment.'),('Wait for metastatic symptoms before biopsy','Localized disease should be evaluated promptly.')],
 'Evaluate the lesion directly','**Clinical, imaging and pathological information should be concordant.**',['A benign-appearing test does not settle a discordant concerning examination.','Imaging choice depends on age and clinical setting.'],'**Follow the breast diagnostic pathway.**',['Review persistent or changing findings after an initial benign assessment.','Do not substitute screening tests for symptomatic evaluation.'],[['Clinical','Mass characteristics'],['Imaging','Appropriate modality'],['Tissue','When indicated to resolve diagnosis']],[BR],style='clinical_scenario')

q('An older adult has new iron-deficiency anemia and occult blood loss without obvious obstruction. Which colorectal presentation is important to investigate?', 'A right-sided colon cancer among possible causes',[
 ('Absence of obstruction excludes colorectal cancer','Right-sided lesions can bleed before causing obstruction.'),('Iron deficiency proves hemorrhoids as the source','A benign visible lesion should not automatically explain the whole pattern.'),('A normal abdominal palpation excludes a colonic lesion','Many cancers are not palpable.')],
 'Tumor location can change the presenting syndrome','**Right-sided cancers can present with chronic blood loss and anemia.**',['Left-sided lesions may more often produce altered bowel habit or obstruction.','These are tendencies rather than absolute rules.'],'**Investigate iron deficiency through an appropriate GI pathway.**',['Assess upper-GI and other causes as indicated.','Do not attribute new deficiency to age alone.'],[['Right colon','Occult bleeding/anemia possible'],['Left colon','Obstructive symptoms may be prominent'],['Assessment','Definitive bowel evaluation']],[CR],style='clinical_scenario')

q('Why is mismatch-repair/MSI assessment important in newly diagnosed colorectal cancer?', 'It can inform inherited-risk evaluation, prognosis and selected treatment decisions',[
 ('It identifies the primary site without histology in every case','It does not replace pathological diagnosis.'),('Every dMMR result proves Lynch syndrome','Sporadic mechanisms can also cause dMMR.'),('It is relevant only after all therapies fail','It can be useful early in the pathway.')],
 'One biomarker can have several distinct roles','**MMR loss can arise from inherited or acquired mechanisms.**',['Protein-loss pattern and follow-up testing help assess etiology.','MSI/dMMR can predict benefit from immune therapy in defined settings.'],'**Use the result in the appropriate hereditary and treatment algorithms.**',['Do not equate a tumor result with confirmed germline status.','Discuss stage-specific implications rather than a universal drug rule.'],[['Hereditary','Lynch workup when indicated'],['Prognostic','Context-specific'],['Predictive','Selected immunotherapy benefit']],[CR])

q('Diffuse gastric wall thickening and poor distensibility persist despite an initially negative superficial mucosal biopsy. Which principle is appropriate?', 'Infiltrative gastric malignancy remains possible and may require deeper or repeat targeted sampling',[
 ('One negative superficial sample excludes linitis plastica','Submucosal infiltration can be missed.'),('The pattern must be benign gastritis','Imaging/endoscopic concern requires resolution.'),('A serum marker alone can establish the diagnosis','Tissue and anatomical assessment remain important.')],
 'Sampling depth must match the disease pattern','**Diffuse infiltrative growth can reduce the yield of a superficial sample.**',['Endoscopic ultrasound or another targeted approach may help.','Other infiltrative diseases remain in the differential.'],'**Resolve pathology–imaging discordance.**',['Avoid repeated identical low-yield sampling without a plan.','Stage and assess nutrition when malignancy is confirmed.'],[['Pattern','Diffuse rigid thickened wall'],['Problem','Superficial sampling may miss'],['Next step','Appropriate deeper/targeted evaluation']],[GA],style='clinical_scenario')

q('Which pairing of esophageal cancer context is most appropriate?', 'Distal adenocarcinoma with Barrett-associated reflux disease',[
 ('All squamous cancers arise only at the gastroesophageal junction','Squamous disease can occur at several esophageal levels.'),('Barrett metaplasia specifically predicts small-cell lung carcinoma','That is a different organ and histology.'),('Reflux history alone establishes adenocarcinoma without biopsy','Histological confirmation is needed.')],
 'Risk associations guide suspicion rather than diagnosis','**Barrett-associated adenocarcinoma often involves the distal esophagus.**',['Squamous carcinoma has different common exposure associations.','Dysphagia, weight loss and bleeding need timely evaluation.'],'**Use endoscopy/biopsy and appropriate staging.**',['Assess nutritional and airway/aspiration consequences.','Do not infer histology solely from symptoms.'],[['Adenocarcinoma','Distal/Barrett association'],['Squamous','Different common exposure pattern'],['Diagnosis','Endoscopic tissue']],[ref('NCI esophageal cancer professional summary','https://www.cancer.gov/types/esophageal/hp/esophageal-treatment-pdq')])

q('A pancreatic body/tail mass causes weight loss and back pain without jaundice. Which statement is correct?', 'Absence of jaundice does not exclude pancreatic cancer because bile-duct obstruction depends on location',[
 ('Every pancreatic cancer must obstruct the common bile duct early','Body/tail disease may not.'),('Back pain proves a benign spinal cause','Visceral malignancy can refer pain to the back.'),('Normal bilirubin guarantees a resectable tumor','Resectability depends on anatomy and spread, not bilirubin alone.')],
 'Anatomy changes symptom timing','**Head lesions more often produce obstructive jaundice than body/tail lesions.**',['Symptoms can remain nonspecific until advanced disease.','Assess diabetes, pancreatitis and other differential considerations.'],'**Use appropriate pancreatic imaging and tissue strategy.**',['Assess vessels, metastatic extent and performance.','Do not delay evaluation because the classic jaundice sign is absent.'],[['Head','Biliary obstruction more likely'],['Body/tail','Pain/weight loss without jaundice'],['Stage','Requires anatomical assessment']],[PA],style='clinical_scenario')

q('A patient with strongly suspicious pancreatic imaging has a normal CA19-9. Which interpretation is appropriate?', 'Cancer remains possible, including in patients who do not express the relevant Lewis antigen',[
 ('Normal CA19-9 excludes pancreatic adenocarcinoma','Sensitivity is incomplete and biological nonexpression occurs.'),('A high CA19-9 would be uniquely diagnostic despite biliary obstruction','Cholestasis and benign conditions can raise it.'),('The marker replaces staging imaging','It does not define resectability or anatomy.')],
 'A marker’s biology limits its use','**CA19-9 is an adjunct rather than a definitive screening or diagnostic assay.**',['Lewis-antigen status and tumor secretion affect the result.','Interpret elevated values with obstruction and inflammation.'],'**Follow the anatomical and pathological diagnostic pathway.**',['Use serial markers appropriately in known marker-producing disease.','Do not treat a normal value as a reason to dismiss a concerning lesion.'],[['Normal marker','Does not exclude'],['Elevated marker','Not uniquely malignant'],['Role','Contextual adjunct']],[PA])
